#!/usr/bin/env node
/**
 * gen-nanp-timezones.mjs — writes lib/crm/nanp-timezones.generated.ts, the
 * NANP (+1) phone prefix -> IANA time zone table the SMS quiet-hours check
 * reads (lib/crm/recipient-timezones.ts, Matt 2026-10-04: "Both zones").
 *
 * Source: Google libphonenumber resources/timezones/map_data.txt, pinned to one
 * commit so a refresh is a deliberate diff, never drift. Apache-2.0; the
 * generated file carries the attribution and says what was changed.
 *
 * Kept: every +1 row except the bare '1' row, which lists all 42 NANP zones.
 * An area code the table does not know must fall back to the market zone
 * alone (the rule before 2026-10-04), not to 42 zones that share no hour.
 *
 * Usage:
 *   node scripts/gen-nanp-timezones.mjs                  # fetch the pinned commit
 *   node scripts/gen-nanp-timezones.mjs --from <file>    # a local map_data.txt
 *   node scripts/gen-nanp-timezones.mjs --sha <commit>   # refresh to another commit
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const PINNED_SHA = '0ae309f1940227efe688f5eb1815ef45a6fbee8d'
const OUT = join(dirname(fileURLToPath(import.meta.url)), '..', 'lib', 'crm', 'nanp-timezones.generated.ts')

function arg(name) {
  const i = process.argv.indexOf(name)
  return i > -1 ? process.argv[i + 1] : undefined
}

/** [prefix, zones] rows for +1, the bare '1' row left out. Exported for tests. */
export function parseNanpRows(text) {
  const rows = []
  for (const line of text.split(/\r?\n/)) {
    const m = /^(1\d+)\|(.+)$/.exec(line.trim())
    if (!m) continue
    rows.push([m[1], m[2].trim()])
  }
  return rows
}

export function renderTable(rows, sha) {
  const short = sha.slice(0, 12)
  const body = rows.map(([prefix, zones]) => `  '${prefix}': '${zones}',`).join('\n')
  return `// GENERATED by scripts/gen-nanp-timezones.mjs. Do not edit by hand.
//
// NANP (+1) phone prefix -> IANA time zone(s), longest prefix wins. Source:
// Google libphonenumber resources/timezones/map_data.txt at commit ${short},
// https://github.com/google/libphonenumber/blob/${sha}/resources/timezones/map_data.txt
// Copyright (C) 2012 The Libphonenumber Authors, licensed under the Apache
// License, Version 2.0 (http://www.apache.org/licenses/LICENSE-2.0). Rows are
// copied unmodified except: only +1 rows, and the bare '1' row (every NANP zone)
// is left out, because an unknown area code must fall back to the market zone,
// not to an intersection of 42 zones with no hour in common.
// Several zones are joined by '&' (an area code or exchange that spans zones).

export const NANP_TIMEZONE_SOURCE = 'libphonenumber ${short} resources/timezones/map_data.txt'

export const NANP_PREFIX_TIMEZONES: Readonly<Record<string, string>> = {
${body}
}
`
}

async function main() {
  const sha = arg('--sha') ?? PINNED_SHA
  const from = arg('--from')
  let text
  if (from) {
    text = readFileSync(from, 'utf8')
  } else {
    const url = `https://raw.githubusercontent.com/google/libphonenumber/${sha}/resources/timezones/map_data.txt`
    const res = await fetch(url)
    if (!res.ok) throw new Error(`fetch ${url}: HTTP ${res.status}`)
    text = await res.text()
  }
  const rows = parseNanpRows(text)
  if (rows.length < 300) throw new Error(`only ${rows.length} +1 rows parsed: not a map_data.txt`)
  writeFileSync(OUT, renderTable(rows, sha))
  console.log(`gen-nanp-timezones: wrote ${rows.length} prefixes from ${sha.slice(0, 12)} to ${OUT}`)
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((e) => {
    console.error(`gen-nanp-timezones: ${e instanceof Error ? e.message : String(e)}`)
    process.exit(1)
  })
}
